//! Generated by Codex. Dispatch lifecycle tasks to the executor driving this worker.

use mudu::common::result::RS;
use std::future::Future;

/// Keeps cleanup independent of the requester while retaining the worker's
/// executor. io_uring workers manually poll their task registry; their Tokio
/// runtime is entered but does not drive spawned Tokio tasks.
pub(crate) fn spawn(future: impl Future<Output = ()> + Send + 'static) -> RS<()> {
    #[cfg(target_os = "linux")]
    if mudu_sys::io::worker_ring::has_current_worker_ring() {
        return mudu_sys::io::worker_ring::with_current_ring(|ring| {
            ring.worker_task_registry().spawn(
                None,
                Box::pin(async move {
                    future.await;
                    Ok(())
                }),
            );
            Ok(())
        });
    }
    mudu_sys::task::async_::spawn_task_detached("procedure-lifecycle", future)?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn lifecycle_runs_on_tokio_without_worker_ring() -> RS<()> {
        let (notify, wait) = mudu_sys::sync::async_::create_notify_wait();
        spawn(async move {
            let _ = notify.notify(42);
        })?;
        assert_eq!(wait.wait().await?, Some(42));
        Ok(())
    }

    #[test]
    #[cfg(target_os = "linux")]
    fn lifecycle_runs_without_polling_tokio_and_survives_request_drop() -> RS<()> {
        use mudu_sys::io::worker_ring::{
            WorkerLocalRing, set_current_worker_ring, unset_current_worker_ring,
        };
        use std::sync::Arc;
        use std::sync::atomic::{AtomicBool, Ordering};

        struct RingGuard;
        impl Drop for RingGuard {
            fn drop(&mut self) {
                unset_current_worker_ring();
            }
        }
        // No Tokio runtime is entered or polled: only the worker registry may
        // drive this task, just like the synchronous io_uring service loop.
        // The worker-ring API uses Arc, but this ring stays on this thread.
        #[expect(clippy::arc_with_non_send_sync)]
        let ring = Arc::new(WorkerLocalRing::new());
        set_current_worker_ring(ring.clone());
        let _ring_guard = RingGuard;
        let completed = Arc::new(AtomicBool::new(false));
        let completed_task = completed.clone();
        let (notify, wait) = mudu_sys::sync::async_::create_notify_wait();
        spawn(async move {
            mudu_utils::yield_now::cooperative_yield_now().await;
            completed_task.store(true, Ordering::Release);
            let _ = notify.notify(());
        })?;
        drop(wait);
        for _ in 0..4 {
            ring.worker_task_registry().drain_completions();
            let (tasks, _) = ring.worker_task_registry().poll_ready_budget(16);
            for task in tasks {
                task.into_result()?;
            }
        }
        assert!(completed.load(Ordering::Acquire));
        assert!(ring.worker_task_registry().is_empty());
        Ok(())
    }
}
